#[test]
fn error_events_and_rejection_events_carry_error_values_without_being_errors() {
    let mut vm = new_storage_test_vm("https://web-error-event-boundaries.test/");

    let result = vm
        .eval(
            r#"
(() => {
  const thrown = new TypeError("boom");
  const errorEvent = new ErrorEvent("error", {
    message: "script boom",
    filename: "script.js",
    lineno: 7,
    colno: 3,
    error: thrown
  });
  const reason = new DOMException("rejected", "AbortError");
  const promise = Promise.reject(reason);
  promise.catch(() => {});
  const rejectionEvent = new PromiseRejectionEvent("unhandledrejection", {
    promise,
    reason
  });
  return [
    errorEvent instanceof Event,
    errorEvent instanceof Error,
    errorEvent instanceof DOMException,
    errorEvent.error === thrown,
    errorEvent.message,
    errorEvent.filename,
    errorEvent.lineno,
    errorEvent.colno,
    rejectionEvent instanceof Event,
    rejectionEvent instanceof Error,
    rejectionEvent instanceof DOMException,
    rejectionEvent.reason === reason,
    rejectionEvent.promise === promise,
    rejectionEvent.reason.name,
    rejectionEvent.reason.code
  ].join("|");
})()
"#,
        )
        .expect("error event boundary probe should evaluate");

    assert_eq!(
        result,
        "true|false|false|true|script boom|script.js|7|3|true|false|false|true|true|AbortError|20"
    );
}

#[test]
fn promise_rejection_event_constructor_parses_required_promise_and_optional_reason() {
    let mut vm = new_storage_test_vm("https://promise-rejection-event-init.test/");

    let result = vm
        .eval(
            r#"
(() => {
  const promise = Promise.resolve("settled");
  const omitted = new PromiseRejectionEvent("unhandledrejection", { promise });
  const explicitUndefined = new PromiseRejectionEvent("unhandledrejection", {
    promise,
    reason: undefined
  });
  const explicitNull = new PromiseRejectionEvent("unhandledrejection", {
    promise,
    reason: null
  });
  const wrapped = new PromiseRejectionEvent("unhandledrejection", { promise: 42 });

  let missingPromiseThrows = false;
  try {
    new PromiseRejectionEvent("unhandledrejection", {});
  } catch (error) {
    missingPromiseThrows = error instanceof TypeError;
  }

  const marker = {};
  let getterErrorPreserved = false;
  try {
    new PromiseRejectionEvent("unhandledrejection", {
      get promise() { throw marker; }
    });
  } catch (error) {
    getterErrorPreserved = error === marker;
  }

  return [
    omitted.promise === promise,
    omitted.reason === undefined,
    explicitUndefined.reason === undefined,
    explicitNull.reason === null,
    wrapped.promise instanceof Promise,
    missingPromiseThrows,
    getterErrorPreserved
  ].join("|");
})()
"#,
        )
        .expect("PromiseRejectionEvent constructor probe should evaluate");

    assert_eq!(result, "true|true|true|true|true|true|true");
}
#[test]
fn internal_dynamic_maps_ignore_object_prototype_pollution() {
    let mut vm = new_storage_test_vm("https://internal-dynamic-map-pollution.test/");

    let result = vm
        .eval(
            r#"
(() => {
  const out = {
    simpleCalls: 0,
    simplePoison: false,
    mqlCalls: 0,
    mqlPoison: false
  };
  try {
    Object.prototype.probe = [() => { out.simplePoison = true; }];
    const target = new EventTarget();
    target.addEventListener("probe", () => { out.simpleCalls++; });
    target.dispatchEvent(new Event("probe"));
    out.simpleProtoLength = Object.prototype.probe.length;

    Object.prototype.change = [() => { out.mqlPoison = true; }];
    const mql = matchMedia("(min-width: 0px)");
    mql.addEventListener("change", () => { out.mqlCalls++; });
    mql.dispatchEvent(new Event("change"));
    out.mqlProtoLength = Object.prototype.change.length;

    Object.prototype.load = [];
    const reader = new FileReader();
    reader.addEventListener("load", () => {});
    out.fileReaderProtoLength = Object.prototype.load.length;

    Object.prototype.loading = [];
    const fonts = typeof FontFaceSet === "function" ? new FontFaceSet() : document.fonts;
    fonts.addEventListener("loading", () => {});
    out.fontFaceSetProtoLength = Object.prototype.loading.length;

    Object.prototype.id = { name: "poisoned", value: "poisoned" };
    const element = document.createElement("div");
    element.setAttribute("id", "actual");
    const attr = element.getAttributeNode("id");
    out.attrName = attr && attr.name;
    out.attrValue = attr && attr.value;
    out.attrPoison = attr === Object.prototype.id;

    return JSON.stringify(out);
  } finally {
    delete Object.prototype.probe;
    delete Object.prototype.change;
    delete Object.prototype.load;
    delete Object.prototype.loading;
    delete Object.prototype.id;
  }
})()
"#,
        )
        .expect("internal dynamic map pollution probe should evaluate");

    assert_eq!(
        result,
        r#"{"simpleCalls":1,"simplePoison":false,"mqlCalls":1,"mqlPoison":false,"simpleProtoLength":1,"mqlProtoLength":1,"fileReaderProtoLength":0,"fontFaceSetProtoLength":0,"attrName":"id","attrValue":"actual","attrPoison":false}"#
    );
}

#[test]
