#[test]
fn navigator_media_capabilities_rejects_insecure_encrypted_queries_as_promises() {
    let mut vm = new_storage_test_vm("http://insecure-media-capabilities.test/");

    let initial = vm
        .eval(
            r#"
            (() => {
              const capabilities = navigator.mediaCapabilities;
              const descriptor = Object.getOwnPropertyDescriptor(
                Navigator.prototype,
                "mediaCapabilities"
              );
              const methodShape = name => {
                const method = Object.getOwnPropertyDescriptor(
                  MediaCapabilities.prototype,
                  name
                );
                return [
                  method.value.name,
                  method.value.length,
                  method.enumerable,
                  method.configurable
                ].join(":");
              };
              const video = {
                contentType: 'video/webm; codecs="vp09.00.10.08"',
                width: 800,
                height: 600,
                bitrate: 3000,
                framerate: 24
              };
              let synchronousThrow = "none";
              let encrypted;
              try {
                encrypted = capabilities.decodingInfo({
                  type: "file",
                  video,
                  keySystemConfiguration: { keySystem: "org.w3.clearkey" }
                });
              } catch (error) {
                synchronousThrow = error && error.name;
              }
              const invalid = capabilities.decodingInfo({
                type: "file",
                keySystemConfiguration: { keySystem: "org.w3.clearkey" }
              });
              const marker = new Error("configuration getter marker");
              const getterFailure = capabilities.decodingInfo({
                type: "file",
                get video() { throw marker; }
              });
              let brandError = "none";
              let brandFailure;
              try {
                brandFailure = MediaCapabilities.prototype.decodingInfo.call({}, {
                  type: "file",
                  video
                });
              } catch (error) {
                brandError = error && error.name;
              }
              globalThis.__mediaCapabilitiesSettlement = "pending";
              Promise.all([
                encrypted.then(
                  () => "encrypted:resolved",
                  error => `encrypted:${error.name}:${error instanceof DOMException}`
                ),
                invalid.then(
                  () => "invalid:resolved",
                  error => `invalid:${error.name}`
                ),
                getterFailure.then(
                  () => "getter:resolved",
                  error => `getter:${error === marker}`
                ),
                brandFailure.then(
                  () => "brand:resolved",
                  error => `brand:${error.name}`
                )
              ]).then(values => {
                globalThis.__mediaCapabilitiesSettlement = values.join("|");
              });
              return JSON.stringify({
                sameObject: capabilities === navigator.mediaCapabilities,
                instance: capabilities instanceof MediaCapabilities,
                tag: Object.prototype.toString.call(capabilities),
                navigatorOwn: Object.hasOwn(navigator, "mediaCapabilities"),
                navigatorDescriptor: [
                  descriptor.get.name,
                  descriptor.get.length,
                  descriptor.enumerable,
                  descriptor.configurable
                ].join(":"),
                methods: [methodShape("decodingInfo"), methodShape("encodingInfo")],
                promise: encrypted instanceof Promise,
                synchronousThrow,
                brandPromise: brandFailure instanceof Promise,
                brandError
              });
            })()
            "#,
        )
        .expect("insecure MediaCapabilities surface should evaluate");

    assert_eq!(
        initial,
        r#"{"sameObject":true,"instance":true,"tag":"[object MediaCapabilities]","navigatorOwn":false,"navigatorDescriptor":"get mediaCapabilities:0:true:true","methods":["decodingInfo:1:true:true","encodingInfo:1:true:true"],"promise":true,"synchronousThrow":"none","brandPromise":true,"brandError":"none"}"#
    );
    assert_eq!(
        vm.eval("String(globalThis.__mediaCapabilitiesSettlement)")
            .expect("MediaCapabilities rejections should settle"),
        "encrypted:SecurityError:true|invalid:TypeError|getter:true|brand:TypeError"
    );
}

#[test]
fn navigator_media_capabilities_resolves_normalized_headless_results() {
    let mut vm = new_storage_test_vm("https://secure-media-capabilities.test/");

    vm.eval(
        r#"
        (() => {
          const decodingConfiguration = {
            type: "file",
            video: {
              contentType: 'video/webm; codecs="vp09.00.10.08"',
              width: 800,
              height: 600,
              bitrate: 3000,
              framerate: 24
            }
          };
          const encodingConfiguration = {
            type: "record",
            audio: { contentType: 'audio/webm; codecs="opus"' }
          };
          globalThis.__mediaCapabilitiesResults = "pending";
          Promise.all([
            navigator.mediaCapabilities.decodingInfo(decodingConfiguration),
            navigator.mediaCapabilities.encodingInfo(encodingConfiguration)
          ]).then(([decoding, encoding]) => {
            globalThis.__mediaCapabilitiesResults = JSON.stringify({
              decoding: [
                typeof decoding.supported,
                decoding.smooth,
                decoding.powerEfficient,
                decoding.keySystemAccess,
                decoding.configuration === decodingConfiguration,
                decoding.configuration.type,
                decoding.configuration.video.framerate
              ],
              encoding: [
                typeof encoding.supported,
                encoding.smooth,
                encoding.powerEfficient,
                encoding.configuration === encodingConfiguration,
                encoding.configuration.type,
                encoding.configuration.audio.contentType
              ]
            });
          });
        })()
        "#,
    )
    .expect("secure MediaCapabilities queries should evaluate");

    assert_eq!(
        vm.eval("String(globalThis.__mediaCapabilitiesResults)")
            .expect("MediaCapabilities results should settle"),
        r#"{"decoding":["boolean",false,false,null,false,"file",24],"encoding":["boolean",false,false,false,"record","audio/webm; codecs=\"opus\""]}"#
    );
}

#[test]
fn dom_point_accessors_use_private_slots_and_reject_forged_receivers() {
    let mut vm = new_storage_test_vm("https://dompoint-internal-slots.test/");

    let result = vm
        .eval(
            r#"
            (() => {
              const stringify = value => value === undefined ? "undefined" : String(value);
              const internalNames = object => Object.getOwnPropertyNames(object)
                .filter(name => name.startsWith("__moliDomPoint"))
                .sort()
                .join(",");
              const descriptorShape = (prototype, receiver, name) => {
                const descriptor = Object.getOwnPropertyDescriptor(prototype, name);
                return [
                  name,
                  typeof descriptor.get,
                  descriptor.get && descriptor.get.name,
                  descriptor.get && descriptor.get.length,
                  typeof descriptor.set,
                  descriptor.set && descriptor.set.name,
                  descriptor.set && descriptor.set.length,
                  descriptor.enumerable,
                  descriptor.configurable,
                  Object.prototype.hasOwnProperty.call(receiver, name)
                ].map(stringify).join(":");
              };
              const probe = callback => {
                try {
                  return String(callback());
                } catch (error) {
                  return error.constructor.name;
                }
              };
              const source = new DOMPoint(7, 8, 9, 10);
              const initialOwnSlots = internalNames(source);
              DOMPoint.prototype.__moliDomPointBrand = true;
              DOMPoint.prototype.__moliDomPointX = -100;
              DOMPoint.prototype.__moliDomPointY = -100;
              DOMPoint.prototype.__moliDomPointZ = -100;
              DOMPoint.prototype.__moliDomPointW = -100;
              const before = [
                source.x,
                source.y,
                source.z,
                source.w,
                JSON.stringify(source.toJSON())
              ].join(":");
              source.x = 11;
              source.y = 12;
              source.z = 13;
              source.w = 14;
              const afterSetter = [
                source.x,
                source.y,
                source.z,
                source.w,
                JSON.stringify(source.toJSON()),
                internalNames(source)
              ].join(":");
              source.__moliDomPointBrand = true;
              source.__moliDomPointX = -200;
              source.__moliDomPointY = -200;
              source.__moliDomPointZ = -200;
              source.__moliDomPointW = -200;
              const afterSpoof = [
                source.x,
                source.y,
                source.z,
                source.w,
                JSON.stringify(source.toJSON()),
                internalNames(source)
              ].join(":");
              const receiver = Object.create(source);
              const descriptor = Object.getOwnPropertyDescriptor(DOMPoint.prototype, "x");
              const fake = Object.assign(Object.create(DOMPoint.prototype), {
                __moliDomPointBrand: true,
                __moliDomPointX: 1,
                __moliDomPointY: 2,
                __moliDomPointZ: 3,
                __moliDomPointW: 4
              });
              return JSON.stringify({
                initialOwnSlots,
                before,
                afterSetter,
                afterSpoof,
                fakeResults: [
                  probe(() => descriptor.get.call(receiver)),
                  probe(() => descriptor.set.call(receiver, 5)),
                  probe(() => DOMPoint.prototype.toJSON.call(receiver)),
                  probe(() => descriptor.get.call(fake)),
                  probe(() => descriptor.set.call(fake, 5)),
                  probe(() => DOMPoint.prototype.toJSON.call(fake))
                ].join(","),
                fakeSlots: internalNames(fake),
                descriptors: ["x", "y", "z", "w"]
                  .map(name => descriptorShape(DOMPoint.prototype, source, name))
                  .join(";")
              });
            })()
            "#,
        )
        .expect("DOMPoint inherited-slot probe should evaluate");

    assert_eq!(
        result,
        r#"{"initialOwnSlots":"","before":"7:8:9:10:{\"x\":7,\"y\":8,\"z\":9,\"w\":10}","afterSetter":"11:12:13:14:{\"x\":11,\"y\":12,\"z\":13,\"w\":14}:","afterSpoof":"11:12:13:14:{\"x\":11,\"y\":12,\"z\":13,\"w\":14}:__moliDomPointBrand,__moliDomPointW,__moliDomPointX,__moliDomPointY,__moliDomPointZ","fakeResults":"TypeError,TypeError,TypeError,TypeError,TypeError,TypeError","fakeSlots":"__moliDomPointBrand,__moliDomPointW,__moliDomPointX,__moliDomPointY,__moliDomPointZ","descriptors":"x:function:get x:0:function:set x:1:true:true:false;y:function:get y:0:function:set y:1:true:true:false;z:function:get z:0:function:set z:1:true:true:false;w:function:get w:0:function:set w:1:true:true:false"}"#
    );
}

#[test]
fn dom_matrix_objects_keep_declared_brand_and_own_slots() {
    let mut vm = new_storage_test_vm("https://dommatrix-declared-slots.test/");

    let result = vm
        .eval(
            r#"
            (() => {
              const stringify = value => value === undefined ? "undefined" : String(value);
              const internalNames = object => Object.getOwnPropertyNames(object)
                .filter(name => name.startsWith("__moliDomMatrix"))
                .sort()
                .join(",");
              const descriptorShape = (prototype, receiver, name) => {
                const descriptor = Object.getOwnPropertyDescriptor(prototype, name);
                return [
                  name,
                  typeof descriptor.get,
                  descriptor.get && descriptor.get.name,
                  descriptor.get && descriptor.get.length,
                  typeof descriptor.set,
                  descriptor.set && descriptor.set.name,
                  descriptor.set && descriptor.set.length,
                  descriptor.enumerable,
                  descriptor.configurable,
                  Object.prototype.hasOwnProperty.call(receiver, name)
                ].map(stringify).join(":");
              };
              const probe = callback => {
                try {
                  return String(callback());
                } catch (error) {
                  return error.constructor.name;
                }
              };
              const mutableNames = [
                "a", "b", "c", "d", "e", "f",
                "m11", "m12", "m13", "m14",
                "m21", "m22", "m23", "m24",
                "m31", "m32", "m33", "m34",
                "m41", "m42", "m43", "m44"
              ];
              const readonlyNames = mutableNames.concat(["is2D", "isIdentity"]);
              const matrix = new DOMMatrix([1, 2, 3, 4, 5, 6]);
              const readonly = DOMMatrixReadOnly.fromMatrix(matrix);
              const initialMatrixSlots = internalNames(matrix);
              const initialReadonlySlots = internalNames(readonly);
              DOMMatrix.prototype.__moliDomMatrixReadOnlyBrand = true;
              DOMMatrix.prototype.__moliDomMatrixMutableBrand = true;
              DOMMatrixReadOnly.prototype.__moliDomMatrixReadOnlyBrand = true;
              for (const name of [
                "__moliDomMatrixM11",
                "__moliDomMatrixM12",
                "__moliDomMatrixM21",
                "__moliDomMatrixM22",
                "__moliDomMatrixM41",
                "__moliDomMatrixM42"
              ]) {
                DOMMatrix.prototype[name] = -100;
                DOMMatrixReadOnly.prototype[name] = -100;
                matrix[name] = -200;
                readonly[name] = -300;
              }
              matrix.__moliDomMatrixReadOnlyBrand = true;
              matrix.__moliDomMatrixMutableBrand = true;
              readonly.__moliDomMatrixReadOnlyBrand = true;
              const receiver = Object.create(matrix);
              const fake = Object.assign(Object.create(DOMMatrix.prototype), {
                __moliDomMatrixReadOnlyBrand: true,
                __moliDomMatrixMutableBrand: true,
                __moliDomMatrixM11: 1,
                __moliDomMatrixM12: 2,
                __moliDomMatrixM21: 3,
                __moliDomMatrixM22: 4,
                __moliDomMatrixM41: 5,
                __moliDomMatrixM42: 6
              });
              const readonlyFake = Object.assign(Object.create(DOMMatrixReadOnly.prototype), {
                __moliDomMatrixReadOnlyBrand: true,
                __moliDomMatrixM11: 1,
                __moliDomMatrixM12: 2,
                __moliDomMatrixM21: 3,
                __moliDomMatrixM22: 4,
                __moliDomMatrixM41: 5,
                __moliDomMatrixM42: 6
              });
              const readonlyDescriptor = Object.getOwnPropertyDescriptor(DOMMatrixReadOnly.prototype, "a");
              const mutableDescriptor = Object.getOwnPropertyDescriptor(DOMMatrix.prototype, "a");
              return JSON.stringify({
                matrixInstance: [
                  matrix instanceof DOMMatrix,
                  matrix instanceof DOMMatrixReadOnly,
                  Object.prototype.toString.call(matrix)
                ].join(","),
                matrixValues: [matrix.a, matrix.b, matrix.c, matrix.d, matrix.e, matrix.f].join(","),
                readonlyInstance: [
                  readonly instanceof DOMMatrixReadOnly,
                  readonly instanceof DOMMatrix,
                  Object.prototype.toString.call(readonly)
                ].join(","),
                readonlyValues: [readonly.a, readonly.b, readonly.c, readonly.d, readonly.e, readonly.f].join(","),
                initialMatrixSlots,
                initialReadonlySlots,
                matrixSpoofSlots: internalNames(matrix),
                readonlySpoofSlots: internalNames(readonly),
                fakeResults: [
                  probe(() => readonlyDescriptor.get.call(receiver)),
                  probe(() => DOMMatrixReadOnly.prototype.toJSON.call(receiver)),
                  probe(() => DOMMatrixReadOnly.prototype.translate.call(receiver, 1, 2)),
                  probe(() => mutableDescriptor.get.call(fake)),
                  probe(() => mutableDescriptor.set.call(fake, 2)),
                  probe(() => DOMMatrix.prototype.translateSelf.call(fake, 1, 2)),
                  probe(() => readonlyDescriptor.get.call(readonlyFake)),
                  probe(() => DOMMatrixReadOnly.prototype.toFloat32Array.call(readonlyFake))
                ].join(","),
                fakeSlots: internalNames(fake),
                readonlyFakeSlots: internalNames(readonlyFake),
                readonlyKeys: Object.keys(DOMMatrixReadOnly.prototype)
                  .filter(name => readonlyNames.includes(name))
                  .join(","),
                mutableKeys: Object.keys(DOMMatrix.prototype)
                  .filter(name => mutableNames.includes(name))
                  .join(","),
                readonlyDescriptors: ["a", "m44", "is2D", "isIdentity"]
                  .map(name => descriptorShape(DOMMatrixReadOnly.prototype, readonly, name))
                  .join(";"),
                mutableDescriptors: ["a", "m44"]
                  .map(name => descriptorShape(DOMMatrix.prototype, matrix, name))
                  .join(";")
              });
            })()
            "#,
        )
        .expect("DOMMatrix declared-slot probe should evaluate");

    assert_eq!(
        result,
        r#"{"matrixInstance":"true,true,[object DOMMatrix]","matrixValues":"1,2,3,4,5,6","readonlyInstance":"true,false,[object DOMMatrixReadOnly]","readonlyValues":"1,2,3,4,5,6","initialMatrixSlots":"","initialReadonlySlots":"","matrixSpoofSlots":"__moliDomMatrixM11,__moliDomMatrixM12,__moliDomMatrixM21,__moliDomMatrixM22,__moliDomMatrixM41,__moliDomMatrixM42,__moliDomMatrixMutableBrand,__moliDomMatrixReadOnlyBrand","readonlySpoofSlots":"__moliDomMatrixM11,__moliDomMatrixM12,__moliDomMatrixM21,__moliDomMatrixM22,__moliDomMatrixM41,__moliDomMatrixM42,__moliDomMatrixReadOnlyBrand","fakeResults":"TypeError,TypeError,TypeError,TypeError,TypeError,TypeError,TypeError,TypeError","fakeSlots":"__moliDomMatrixM11,__moliDomMatrixM12,__moliDomMatrixM21,__moliDomMatrixM22,__moliDomMatrixM41,__moliDomMatrixM42,__moliDomMatrixMutableBrand,__moliDomMatrixReadOnlyBrand","readonlyFakeSlots":"__moliDomMatrixM11,__moliDomMatrixM12,__moliDomMatrixM21,__moliDomMatrixM22,__moliDomMatrixM41,__moliDomMatrixM42,__moliDomMatrixReadOnlyBrand","readonlyKeys":"a,b,c,d,e,f,m11,m12,m13,m14,m21,m22,m23,m24,m31,m32,m33,m34,m41,m42,m43,m44,is2D,isIdentity","mutableKeys":"a,b,c,d,e,f,m11,m12,m13,m14,m21,m22,m23,m24,m31,m32,m33,m34,m41,m42,m43,m44","readonlyDescriptors":"a:function:get a:0:undefined:undefined:undefined:true:true:false;m44:function:get m44:0:undefined:undefined:undefined:true:true:false;is2D:function:get is2D:0:undefined:undefined:undefined:true:true:false;isIdentity:function:get isIdentity:0:undefined:undefined:undefined:true:true:false","mutableDescriptors":"a:function:get a:0:function:set a:1:true:true:false;m44:function:get m44:0:function:set m44:1:true:true:false"}"#
    );
}

#[test]
fn element_animate_autoplays_and_settles_finished_promise() {
    let mut vm = new_parsed_test_vm("https://animations.test/", "<!doctype html><body></body>");

    vm.eval(
        r#"
        (() => {
          globalThis.__animationProbe = [];
          const animation = document.body.animate(
            { opacity: [0, 1] },
            { duration: 1 }
          );
          globalThis.__animationProbe.push(animation.playState);
          animation.finished.then(() => {
            globalThis.__animationProbe.push(animation.playState);
          });
        })()
        "#,
    )
    .expect("Element.animate probe should evaluate");

    assert_eq!(
        vm.eval("globalThis.__animationProbe.join('|')")
            .expect("animation probe should be readable"),
        "running|finished"
    );
}

#[test]
fn element_get_animations_tracks_script_created_animations() {
    let mut vm = new_parsed_test_vm(
        "https://animation-registry.test/",
        "<!doctype html><body><div id=\"first\"></div><div id=\"second\"></div></body>",
    );

    let result = vm
        .eval(
            r#"
            (() => {
              const first = document.getElementById("first");
              const second = document.getElementById("second");
              const animation = first.animate(
                [{ opacity: 1 }, { opacity: 0 }],
                1000
              );

              const initial = first.getAnimations();
              const secondInitial = second.getAnimations();
              animation.pause();
              const paused = first.getAnimations();
              animation.cancel();
              const cancelled = first.getAnimations();
              animation.play();
              const replayed = first.getAnimations();
              animation.finish();
              const finished = first.getAnimations();

              const manual = new Animation(
                new KeyframeEffect(first, [{ opacity: 0 }], 1000),
                document.timeline
              );
              manual.play();
              const manuallyPlayed = first.getAnimations();

              return JSON.stringify({
                initial: [initial.length, initial[0] === animation],
                secondInitial: secondInitial.length,
                paused: [paused.length, paused[0] === animation],
                cancelled: cancelled.length,
                replayed: [replayed.length, replayed[0] === animation],
                finished: finished.length,
                manuallyPlayed: [
                  manuallyPlayed.length,
                  manuallyPlayed[0] === manual
                ]
              });
            })()
            "#,
        )
        .expect("Element.getAnimations registry probe should evaluate");

    assert_eq!(
        result,
        r#"{"initial":[1,true],"secondInitial":0,"paused":[1,true],"cancelled":0,"replayed":[1,true],"finished":0,"manuallyPlayed":[1,true]}"#
    );
}

#[test]
fn animation_internal_callback_state_ignores_public_spoofing() {
    let mut vm = new_parsed_test_vm(
        "https://animations-callback-slots.test/page.html",
        "<!doctype html><body></body>",
    );

    let initial = vm
        .eval(
            r#"
            (() => {
              globalThis.__animationCallbackEvents = [];
              Object.defineProperties(Object.prototype, {
                __moliAnimationPromiseResolve: {
                  configurable: true,
                  value: () => globalThis.__animationCallbackEvents.push("prototype-resolve")
                },
                __moliAnimationMicrotaskAnimation: {
                  configurable: true,
                  value: null
                },
                __moliAnimationMicrotaskToken: {
                  configurable: true,
                  value: -1
                }
              });
              const target = document.body.appendChild(document.createElement("div"));
              const animation = target.animate(
                { backgroundImage: ["url(real.png)", "url(real.png)"] },
                { duration: 1 }
              );
              const ownNames = Object.getOwnPropertyNames(animation)
                .filter(name => name.startsWith("__moliAnimation"))
                .sort();
              Object.defineProperties(animation, {
                __moliAnimationPromiseResolve: {
                  configurable: true,
                  value: () => globalThis.__animationCallbackEvents.push("own-resolve")
                },
                __moliAnimationMicrotaskAnimation: {
                  configurable: true,
                  value: null
                },
                __moliAnimationMicrotaskToken: {
                  configurable: true,
                  value: -1
                }
              });
              animation.finished.then(
                () => {
                  globalThis.__animationCallbackEvents.push(
                    `finished:${animation.playState}:${getComputedStyle(target).backgroundImage}`
                  );
                },
                error => {
                  globalThis.__animationCallbackEvents.push(`rejected:${error && error.name}`);
                }
              );
              return JSON.stringify({ ownNames, events: globalThis.__animationCallbackEvents });
            })()
            "#,
        )
        .expect("Animation internal callback spoofing setup should evaluate");
    assert_eq!(initial, r#"{"ownNames":[],"events":[]}"#);

    let settled = vm
        .eval("JSON.stringify(globalThis.__animationCallbackEvents)")
        .expect("Animation internal callback promise should settle");
    assert_eq!(
        settled,
        r#"["finished:finished:url(\"https://animations-callback-slots.test/real.png\")"]"#
    );
}

#[test]
fn animation_declared_prototype_methods_preserve_descriptors_and_behavior() {
    let mut vm = new_parsed_test_vm(
        "https://animations-declared-methods.test/",
        "<!doctype html><body><div id=\"target\"></div></body>",
    );

    let result = vm
        .eval(
            r#"
            (() => {
              const target = document.getElementById("target");
              const descriptors = [
                [Element.prototype, "animate", 0],
                [Element.prototype, "getAnimations", 0],
                [KeyframeEffect.prototype, "setKeyframes", 1],
                [Animation.prototype, "play", 0],
                [Animation.prototype, "pause", 0],
                [Animation.prototype, "cancel", 0],
                [Animation.prototype, "finish", 0],
                [Animation.prototype, "reverse", 0],
                [Animation.prototype, "commitStyles", 0],
              ].map(([prototype, name, expectedLength]) => {
                const descriptor = Object.getOwnPropertyDescriptor(prototype, name);
                return [
                  name,
                  typeof descriptor?.value,
                  descriptor?.value?.name,
                  descriptor?.value?.length,
                  expectedLength,
                  descriptor?.enumerable,
                  descriptor?.writable,
                  descriptor?.configurable
                ].join(":");
              });
              const effect = new KeyframeEffect(target, [{ opacity: 0 }], 1000);
              const setKeyframesResult = effect.setKeyframes([{ opacity: 1 }]) === undefined;
              const animation = target.animate({ opacity: [0, 1] }, { duration: 1 });
              const animations = target.getAnimations();
              return JSON.stringify({
                descriptors,
                setKeyframesResult,
                animationInstance: animation instanceof Animation,
                animationState: animation.playState,
                animationsIsArray: Array.isArray(animations),
              });
            })()
            "#,
        )
        .expect("Animation declared prototype method probe should evaluate");

    assert_eq!(
        result,
        r#"{"descriptors":["animate:function:animate:0:0:true:true:true","getAnimations:function:getAnimations:0:0:true:true:true","setKeyframes:function:setKeyframes:1:1:true:true:true","play:function:play:0:0:true:true:true","pause:function:pause:0:0:true:true:true","cancel:function:cancel:0:0:true:true:true","finish:function:finish:0:0:true:true:true","reverse:function:reverse:0:0:true:true:true","commitStyles:function:commitStyles:0:0:true:true:true"],"setKeyframesResult":true,"animationInstance":true,"animationState":"running","animationsIsArray":true}"#
    );
}

