#[test]
fn animation_private_slots_ignore_reflection_and_spoofing() {
    let mut vm = new_parsed_test_vm(
        "https://animations-declared-slots.test/page.html",
        "<!doctype html><body><div id=\"target\"></div></body>",
    );

    let result = vm
        .eval(
            r#"
            (() => {
              const target = document.getElementById("target");
              const realEffect = new KeyframeEffect(target, [
                { backgroundImage: "url(real.png)" }
              ], 1000);
              const animation = new Animation(realEffect, document.timeline);
              let onfinishCount = 0;
              animation.onfinish = () => {
                onfinishCount += 1;
              };
              const animationOwnSlots = Object.getOwnPropertyNames(animation)
                .filter(name => name.startsWith("__moliAnimation"))
                .sort();
              const keyframeOwnSlots = Object.getOwnPropertyNames(realEffect)
                .filter(name => name.startsWith("__moliKeyframeEffect"))
                .sort();

              const protoEffect = new KeyframeEffect(target, [
                { backgroundImage: "url(proto.png)" }
              ], 1000);
              Animation.prototype.__moliAnimationPlayState = "running";
              Animation.prototype.__moliAnimationEffect = protoEffect;
              Animation.prototype.__moliAnimationTimeline = document.timeline;
              Animation.prototype.__moliAnimationStartTime = 12;
              Animation.prototype.__moliAnimationOnfinish = () => {
                throw new Error("prototype onfinish");
              };
              Animation.prototype.__moliAnimationFinishedResolve = () => {
                throw new Error("prototype resolve");
              };
              Animation.prototype.__moliAnimationFinishToken = 99;
              KeyframeEffect.prototype.__moliKeyframeEffectTarget = target;
              KeyframeEffect.prototype.__moliKeyframeEffectKeyframes = [
                { backgroundImage: "url(proto-keyframe.png)" }
              ];
              Object.defineProperties(animation, {
                __moliAnimationEffect: { value: protoEffect, configurable: true },
                __moliAnimationPlayState: { value: "paused", configurable: true },
                __moliAnimationOnfinish: {
                  value: () => { throw new Error("own onfinish"); },
                  configurable: true
                },
                __moliAnimationFinishedResolve: {
                  value: () => { throw new Error("own resolve"); },
                  configurable: true
                }
              });
              Object.defineProperty(realEffect, "__moliKeyframeEffectKeyframes", {
                value: [{ backgroundImage: "url(raw-own.png)" }],
                configurable: true
              });
              const pollutedAnimationOwnSlots = Object.getOwnPropertyNames(animation)
                .filter(name => name.startsWith("__moliAnimation"))
                .sort();
              const pollutedKeyframeOwnSlots = Object.getOwnPropertyNames(realEffect)
                .filter(name => name.startsWith("__moliKeyframeEffect"))
                .sort();

              animation.play();
              const realAfterPlay = getComputedStyle(target).backgroundImage;
              const realStateAfterPlay = animation.playState;
              let realFinish;
              try {
                animation.finish();
                realFinish = "ok";
              } catch (error) {
                realFinish = `throw:${error && error.message}`;
              }
              const realStateAfterFinish = animation.playState;
              const realOnfinishCount = onfinishCount;
              realEffect.setKeyframes([
                { backgroundImage: "url(updated.png)" }
              ]);
              animation.cancel();
              const realAfterCancel = getComputedStyle(target).backgroundImage;
              animation.play();
              const realAfterSetKeyframes = getComputedStyle(target).backgroundImage;
              target.style.backgroundImage = "";

              const fakeAnimation = Object.create(Animation.prototype);
              const fakeEffect = Object.create(KeyframeEffect.prototype);
              KeyframeEffect.prototype.setKeyframes.call(fakeEffect, [
                { backgroundImage: "url(fake-own.png)" }
              ]);
              const fakeEffectOwnSlots = Object.getOwnPropertyNames(fakeEffect)
                .filter(name => name.startsWith("__moliKeyframeEffect"))
                .sort();

              const before = target.style.backgroundImage || "";
              Animation.prototype.play.call(fakeAnimation);
              const afterPlay = target.style.backgroundImage || "";
              const fakeAnimationOwnSlotsAfterPlay = Object.getOwnPropertyNames(fakeAnimation)
                .filter(name => name.startsWith("__moliAnimation"))
                .sort();
              let finish;
              try {
                Animation.prototype.finish.call(fakeAnimation);
                finish = "ok";
              } catch (error) {
                finish = `throw:${error && error.message}`;
              }
              const afterFinish = target.style.backgroundImage || "";

              return JSON.stringify({
                animationOwnSlots,
                keyframeOwnSlots,
                pollutedAnimationOwnSlots,
                pollutedKeyframeOwnSlots,
                fakeEffectOwnSlots,
                fakeAnimationOwnSlotsAfterPlay,
                finish,
                real: [
                  realStateAfterPlay,
                  realAfterPlay,
                  realFinish,
                  realStateAfterFinish,
                  realOnfinishCount,
                  realAfterCancel,
                  realAfterSetKeyframes
                ].join("|"),
                fake: [
                  before,
                  afterPlay,
                  afterFinish
                ].join("|")
              });
            })()
            "#,
        )
        .expect("Animation declared-slot probe should evaluate");

    assert_eq!(
        result,
        r#"{"animationOwnSlots":[],"keyframeOwnSlots":[],"pollutedAnimationOwnSlots":["__moliAnimationEffect","__moliAnimationFinishedResolve","__moliAnimationOnfinish","__moliAnimationPlayState"],"pollutedKeyframeOwnSlots":["__moliKeyframeEffectKeyframes"],"fakeEffectOwnSlots":[],"fakeAnimationOwnSlotsAfterPlay":[],"finish":"ok","real":"running|url(\"https://animations-declared-slots.test/real.png\")|ok|finished|1|none|url(\"https://animations-declared-slots.test/updated.png\")","fake":"||"}"#
    );
}

#[test]
fn toggle_event_init_uses_webidl_dom_string_conversion() {
    let mut vm = new_storage_test_vm("https://toggle-event-init.test/");

    let result = vm
        .eval(
            r#"
            (() => {
              const probe = fn => {
                try {
                  return fn();
                } catch (error) {
                  return `throw:${error && error.name}`;
                }
              };
              const source = document.createElement("button");
              const nullish = new ToggleEvent("toggle", {
                oldState: null,
                newState: undefined,
                source
              });
              const defaults = new ToggleEvent("toggle", {});
              const missing = new ToggleEvent("toggle");
              const readonly = probe(() => {
                nullish.oldState = "changed";
                return nullish.oldState;
              });
              return JSON.stringify({
                oldNull: nullish.oldState,
                newUndefined: nullish.newState,
                sourceMatches: nullish.source === source,
                defaultOld: defaults.oldState,
                defaultNew: defaults.newState,
                defaultSource: defaults.source === null,
                missingOld: missing.oldState,
                missingNew: missing.newState,
                readonly,
                symbol: probe(() => new ToggleEvent("toggle", { oldState: Symbol("x") }))
              });
            })()
            "#,
        )
        .expect("ToggleEventInit conversion probe should evaluate");

    assert_eq!(
        result,
        r#"{"oldNull":"null","newUndefined":"","sourceMatches":true,"defaultOld":"","defaultNew":"","defaultSource":true,"missingOld":"","missingNew":"","readonly":"null","symbol":"throw:TypeError"}"#
    );
}
#[test]
fn removing_open_popover_clears_internal_open_state_before_reinsertion() {
    let mut vm = new_storage_test_vm("https://popover-removal-state.test/");

    let result = vm
        .eval(
            r#"
            (() => {
              const popover = document.createElement("div");
              popover.setAttribute("popover", "");
              const html = document.appendChild(document.createElement("html"));
              const body = html.appendChild(document.createElement("body"));
              body.appendChild(popover);
              popover.showPopover();
              const before = popover.matches(":popover-open");
              popover.remove();
              const disconnected = popover.matches(":popover-open");
              body.appendChild(popover);
              const reinserted = popover.matches(":popover-open");
              return [before, disconnected, reinserted].join("|");
            })()
            "#,
        )
        .expect("popover removal state probe should evaluate");

    assert_eq!(result, "true|false|false");
}

#[test]
fn moving_open_popover_between_documents_clears_internal_open_state() {
    let mut vm = new_storage_test_vm("https://popover-cross-document.test/");

    let result = vm
        .eval(
            r#"
            (() => {
              const html = document.appendChild(document.createElement("html"));
              const body = html.appendChild(document.createElement("body"));
              const frame1 = document.createElement("iframe");
              const frame2 = document.createElement("iframe");
              body.append(frame1, frame2);
              const bodyFor = doc => doc.body || doc.appendChild(doc.createElement("body"));
              const popover = frame1.contentDocument.createElement("div");
              popover.setAttribute("popover", "");
              bodyFor(frame1.contentDocument).appendChild(popover);
              popover.showPopover();
              const before = popover.matches(":popover-open");
              bodyFor(frame2.contentDocument).appendChild(popover);
              const moved = popover.matches(":popover-open");
              popover.showPopover();
              const reshown = popover.matches(":popover-open");
              return [before, moved, reshown].join("|");
            })()
            "#,
        )
        .expect("popover cross-document move probe should evaluate");

    assert_eq!(result, "true|false|true");
}

#[tokio::test]
async fn showing_popover_focuses_autofocus_descendant_before_toggle_event() {
    let loader = ResourceRequestClient::new(&moli_fetch::FetchConfig::default()).expect("loader");
    let mut vm = new_storage_page_task_executor_test_vm("https://popover-autofocus.test/");

    let before = vm
        .eval(
            r#"
            (() => {
              const html = document.appendChild(document.createElement("html"));
              const body = html.appendChild(document.createElement("body"));
              const button = document.createElement("button");
              const popover = document.createElement("div");
              const focusTarget = document.createElement("button");
              popover.setAttribute("popover", "");
              focusTarget.autofocus = true;
              popover.appendChild(focusTarget);
              body.append(button, popover);
              globalThis.__lmPopoverFocusEvents = [];
              popover.addEventListener("beforetoggle", e => globalThis.__lmPopoverFocusEvents.push(`${e.type}:${e.oldState}->${e.newState}`));
              popover.addEventListener("toggle", e => globalThis.__lmPopoverFocusEvents.push(`${e.type}:${e.oldState}->${e.newState}`));
              button.addEventListener("blur", () => globalThis.__lmPopoverFocusEvents.push("button blur"));
              focusTarget.addEventListener("focus", () => globalThis.__lmPopoverFocusEvents.push("focusTarget focus"));
              button.focus();
              popover.showPopover();
              return globalThis.__lmPopoverFocusEvents.join("|");
            })()
            "#,
        )
        .expect("popover autofocus setup should evaluate");

    assert_eq!(
        before,
        "beforetoggle:closed->open|button blur|focusTarget focus"
    );

    assert!(!vm.has_ready_timeout());
    assert!(
        vm.run_one_dom_manipulation_task_executor_turn(
            PageDomManipulationTestFamily::ElementToggle,
            &loader,
        )
        .await
        .expect("queued popover toggle task should run")
    );

    let after = vm
        .eval(
            r#"
            (() => globalThis.__lmPopoverFocusEvents.join("|"))()
            "#,
        )
        .expect("popover autofocus event order should evaluate");

    assert_eq!(
        after,
        "beforetoggle:closed->open|button blur|focusTarget focus|toggle:closed->open"
    );
}
