#[tokio::test]
async fn navigator_service_worker_respond_with_argument_type_controls_fetch_and_xhr_results() {
    let (base_url, server) = spawn_service_worker_response_server(vec![(
        "/app/worker.js",
        "text/javascript; charset=utf-8",
        r#"
            self.addEventListener("install", event => {
              event.waitUntil(Promise.resolve());
            });
            self.addEventListener("activate", event => {
              event.waitUntil(clients.claim());
            });
            self.addEventListener("fetch", event => {
              const testcase = new URL(event.request.url).search;
              switch (testcase) {
                case "?response-object":
                  event.respondWith(new Response("direct-body", {status: 211}));
                  break;
                case "?response-promise-object":
                  event.respondWith(Promise.resolve(new Response("promise-body", {status: 212})));
                  break;
                case "?other-value":
                  event.respondWith({not: "a response"});
                  break;
              }
            });
            "#,
    )])
    .await;
    let loader = ResourceRequestClient::new(&moli_fetch::FetchConfig::default()).expect("loader");
    let (mut vm, browser_context_runtime) =
        new_service_worker_page_test_vm_with_loader_and_browser_context_runtime(
            &format!("{base_url}/app/page.html"),
            &loader,
        );

    vm.eval(
        r#"
            (() => {
              globalThis.__serviceWorkerRespondWithArgumentProbe = "pending";
              (async () => {
                await navigator.serviceWorker.register("worker.js", { scope: "./" });
                await navigator.serviceWorker.ready;
                const direct = await fetch("api/data.txt?response-object");
                const promised = await fetch("api/data.txt?response-promise-object");
                let invalidResult;
                try {
                  await fetch("api/data.txt?other-value");
                  invalidResult = "unexpected-resolve";
                } catch (error) {
                  invalidResult = [
                    error && error.name,
                    String(error && error.message).includes("FetchEvent.respondWith requires a Response")
                  ].join(":");
                }
                const runXhr = name => new Promise(resolve => {
                  const xhr = new XMLHttpRequest();
                  xhr.onload = () => resolve([
                    name,
                    "load",
                    xhr.readyState,
                    xhr.status,
                    xhr.statusText,
                    xhr.responseText
                  ].join(":"));
                  xhr.onerror = () => resolve([
                    name,
                    "error",
                    xhr.readyState,
                    xhr.status,
                    xhr.statusText,
                    xhr.responseText
                  ].join(":"));
                  xhr.open("GET", "api/xhr-data.txt?" + name);
                  xhr.send();
                });
                globalThis.__serviceWorkerRespondWithArgumentProbe = [
                  direct.status,
                  await direct.text(),
                  promised.status,
                  await promised.text(),
                  invalidResult,
                  await runXhr("response-object"),
                  await runXhr("response-promise-object"),
                  await runXhr("other-value")
                ].join("|");
              })().catch((error) => {
                globalThis.__serviceWorkerRespondWithArgumentProbe =
                  "error:" + String(error && error.name) + ":" + String(error && error.message);
              });
            })()
            "#,
    )
    .expect("service worker respondWith argument probe should evaluate");

    drain_service_worker_test_until_eval_equals(
        &mut vm,
        &browser_context_runtime,
        &loader,
        "String(globalThis.__serviceWorkerRespondWithArgumentProbe)",
        concat!(
            "211|direct-body|212|promise-body|TypeError:true|",
            "response-object:load:4:211::direct-body|",
            "response-promise-object:load:4:212::promise-body|",
            "other-value:error:4:0::"
        ),
    )
    .await;

    server
        .await
        .expect("service worker respondWith argument server should finish");
}

#[tokio::test]
async fn navigator_service_worker_fetch_event_network_error_xhr_matrix() {
    let (base_url, server) = spawn_service_worker_response_server(vec![
        (
            "/app/worker.js",
            "text/javascript; charset=utf-8",
            r#"
            self.addEventListener("install", event => {
              event.waitUntil(Promise.resolve());
            });
            self.addEventListener("activate", event => {
              event.waitUntil(clients.claim());
            });
            self.addEventListener("fetch", () => {});
            self.addEventListener("fetch", event => {
              const testcase = new URL(event.request.url).search;
              switch (testcase) {
                case "?reject":
                  event.respondWith(Promise.reject(new Error("rejected")));
                  break;
                case "?prevent-default":
                  event.preventDefault();
                  break;
                case "?prevent-default-and-respond-with":
                  event.preventDefault();
                  break;
                case "?unused-body":
                  event.respondWith(new Response("body"));
                  break;
                case "?used-body": {
                  const response = new Response("body");
                  response.text();
                  event.respondWith(response);
                  break;
                }
                case "?unused-fetched-body":
                  event.respondWith(fetch("other.html").then(response => response));
                  break;
                case "?used-fetched-body":
                  event.respondWith(fetch("other.html").then(response => {
                    response.text();
                    return response;
                  }));
                  break;
                case "?throw-exception":
                  throw new Error("boom");
              }
            });
            self.addEventListener("fetch", () => {});
            self.addEventListener("fetch", event => {
              if (new URL(event.request.url).search === "?prevent-default-and-respond-with") {
                event.respondWith(new Response("responding!"));
              }
            });
            self.addEventListener("fetch", () => {});
            "#,
        ),
        ("/app/other.html", "text/plain", "other-body"),
        ("/app/other.html", "text/plain", "other-body-used"),
        (
            "/app/api/network-error?throw-exception",
            "text/plain",
            "fallback-body",
        ),
    ])
    .await;
    let loader = ResourceRequestClient::new(&moli_fetch::FetchConfig::default()).expect("loader");
    let (mut vm, browser_context_runtime) =
        new_service_worker_page_test_vm_with_loader_and_browser_context_runtime(
            &format!("{base_url}/app/page.html"),
            &loader,
        );

    vm.eval(
        r#"
            (() => {
              globalThis.__serviceWorkerNetworkErrorProbe = "pending";
              (async () => {
                await navigator.serviceWorker.register("worker.js", { scope: "./" });
                await navigator.serviceWorker.ready;
                const run = name => new Promise(resolve => {
                  const xhr = new XMLHttpRequest();
                  xhr.onload = () => resolve([
                    name,
                    "load",
                    xhr.readyState,
                    xhr.status,
                    xhr.statusText,
                    xhr.responseText
                  ].join(":"));
                  xhr.onerror = () => resolve([
                    name,
                    "error",
                    xhr.readyState,
                    xhr.status,
                    xhr.statusText,
                    xhr.responseText
                  ].join(":"));
                  xhr.open("GET", "api/network-error?" + name);
                  xhr.send();
                });
                const cases = [
                  "prevent-default-and-respond-with",
                  "prevent-default",
                  "reject",
                  "unused-body",
                  "used-body",
                  "unused-fetched-body",
                  "used-fetched-body",
                  "throw-exception"
                ];
                globalThis.__serviceWorkerNetworkErrorProbe =
                  (await cases.reduce(
                    (promise, name) => promise.then(async results => {
                      results.push(await run(name));
                      return results;
                    }),
                    Promise.resolve([])
                  )).join("|");
              })().catch(error => {
                globalThis.__serviceWorkerNetworkErrorProbe =
                  "error:" + String(error && error.name) + ":" + String(error && error.message);
              });
            })()
            "#,
    )
    .expect("service worker network error probe should evaluate");

    drain_service_worker_test_until_eval_equals(
        &mut vm,
        &browser_context_runtime,
        &loader,
        "String(globalThis.__serviceWorkerNetworkErrorProbe)",
        concat!(
            "prevent-default-and-respond-with:load:4:200::responding!|",
            "prevent-default:error:4:0::|",
            "reject:error:4:0::|",
            "unused-body:load:4:200::body|",
            "used-body:error:4:0::|",
            "unused-fetched-body:load:4:200:OK:other-body|",
            "used-fetched-body:error:4:0::|",
            "throw-exception:load:4:200:OK:fallback-body"
        ),
    )
    .await;

    server
        .await
        .expect("service worker network error server should finish");
}

#[tokio::test]
async fn navigator_service_worker_respond_with_propagation_and_throw_browser_matrix() {
    let (base_url, server) = spawn_service_worker_response_server(vec![
        (
            "/app/worker.js",
            "text/javascript; charset=utf-8",
            r#"
            self.addEventListener("install", event => {
              event.waitUntil(Promise.resolve());
            });
            self.addEventListener("activate", event => {
              event.waitUntil(clients.claim());
            });

            const propagationOrder = [];

            self.addEventListener("fetch", event => {
              const testcase = new URL(event.request.url).search;
              if (testcase === "?stops-propagation") {
                propagationOrder.push("first");
                event.respondWith(Promise.resolve().then(() => new Response(
                  propagationOrder.join(","),
                  {status: 214}
                )));
                return;
              }
              if (testcase === "?throws-after") {
                event.respondWith(new Response("intercepted", {status: 215}));
                throw new Error("after-respond");
              }
              if (testcase === "?double") {
                let secondResult = "unset";
                event.respondWith(Promise.resolve().then(() => new Response(
                  secondResult,
                  {status: 216}
                )));
                try {
                  event.respondWith(new Response("second"));
                  secondResult = "resolved";
                } catch (error) {
                  secondResult = error && error.name;
                }
              }
              if (testcase === "?microtask") {
                Promise.resolve().then(() => {
                  event.respondWith(new Response("microtask", {status: 217}));
                });
              }
              if (testcase === "?task") {
                const clientId = event.clientId;
                setTimeout(() => {
                  let result = "unset";
                  try {
                    event.respondWith(new Response("task-response"));
                    result = "resolved";
                  } catch (error) {
                    result = error && error.name;
                  }
                  clients.get(clientId).then(client => {
                    if (client) client.postMessage("task:" + result);
                  });
                }, 0);
              }
            });

            self.addEventListener("fetch", event => {
              if (new URL(event.request.url).search === "?stops-propagation") {
                propagationOrder.push("second");
              }
            });
            "#,
        ),
        (
            "/app/api/respondwith?task",
            "text/plain; charset=utf-8",
            "task-fallback",
        ),
    ])
    .await;
    let loader = ResourceRequestClient::new(&moli_fetch::FetchConfig::default()).expect("loader");
    let (mut vm, browser_context_runtime) =
        new_service_worker_page_test_vm_with_loader_and_browser_context_runtime(
            &format!("{base_url}/app/page.html"),
            &loader,
        );

    vm.eval(
        r#"
            (() => {
              globalThis.__serviceWorkerRespondWithPropagationProbe = "pending";
              (async () => {
                await navigator.serviceWorker.register("worker.js", { scope: "./" });
                await navigator.serviceWorker.ready;
                const queuedMessages = [];
                const messageResolvers = [];
                navigator.serviceWorker.onmessage = event => {
                  if (messageResolvers.length > 0) {
                    messageResolvers.shift()(event.data);
                  } else {
                    queuedMessages.push(event.data);
                  }
                };
                const nextMessage = () => {
                  if (queuedMessages.length > 0) {
                    return Promise.resolve(queuedMessages.shift());
                  }
                  return new Promise(resolve => messageResolvers.push(resolve));
                };
                const run = async testcase => {
                  const response = await fetch("api/respondwith" + testcase);
                  return [response.status, await response.text()].join(":");
                };
                const runTask = async () => {
                  const responsePromise = fetch("api/respondwith?task");
                  const message = await nextMessage();
                  const response = await responsePromise;
                  return [response.status, await response.text(), message].join(":");
                };
                globalThis.__serviceWorkerRespondWithPropagationProbe = [
                  await run("?stops-propagation"),
                  await run("?throws-after"),
                  await run("?double"),
                  await run("?microtask"),
                  await runTask()
                ].join("|");
              })().catch(error => {
                globalThis.__serviceWorkerRespondWithPropagationProbe =
                  "error:" + String(error && error.name) + ":" + String(error && error.message);
              });
            })()
            "#,
    )
    .expect("service worker respondWith propagation probe should evaluate");

    drain_service_worker_test_until_eval_equals(
        &mut vm,
        &browser_context_runtime,
        &loader,
        "String(globalThis.__serviceWorkerRespondWithPropagationProbe)",
        "214:first|215:intercepted|216:InvalidStateError|217:microtask|200:task-fallback:task:InvalidStateError",
    )
    .await;

    server
        .await
        .expect("service worker respondWith propagation server should finish");
}

#[tokio::test]
async fn navigator_service_worker_child_frame_controller_uses_child_client() {
    let (base_url, server) = spawn_service_worker_response_server(vec![
        (
            "/app/worker.js",
            "text/javascript; charset=utf-8",
            r#"
            self.addEventListener("install", event => {
              event.waitUntil(Promise.resolve());
            });
            self.addEventListener("activate", event => {
              event.waitUntil(clients.claim());
            });
            self.addEventListener("message", event => {
              const source = event.source;
              event.data.port.postMessage([
                "child-controller-reply",
                event.constructor && event.constructor.name,
                event instanceof ExtendableMessageEvent,
                event instanceof ExtendableEvent,
                event instanceof Event,
                Object.prototype.toString.call(event),
                event.origin,
                event.lastEventId,
                event.ports.length,
                event.ports[0] instanceof MessagePort,
                source && source.constructor && source.constructor.name,
                source instanceof WindowClient,
                source instanceof Client,
                source && source.type,
                source && source.frameType,
                source && source.url,
                source && source.visibilityState,
                source && source.focused
              ].join("|"));
            });
            "#,
        ),
        (
            "/app/frame.html",
            "text/html; charset=utf-8",
            "<!doctype html><title>frame</title>",
        ),
    ])
    .await;
    let loader = ResourceRequestClient::new(&moli_fetch::FetchConfig::default()).expect("loader");
    let (mut vm, browser_context_runtime) =
        new_service_worker_page_test_vm_with_loader_and_browser_context_runtime(
            &format!("{base_url}/app/page.html"),
            &loader,
        );

    vm.eval(
        r#"
            (() => {
              globalThis.__serviceWorkerChildControllerProbe = "pending";
              (async () => {
                await navigator.serviceWorker.register("worker.js", { scope: "./" });
                await navigator.serviceWorker.ready;
                const frame = document.createElement("iframe");
                const loaded = new Promise((resolve, reject) => {
                  frame.onload = resolve;
                  frame.onerror = () => reject(new Error("frame load failed"));
                });
                frame.src = "frame.html";
                (document.body || document.documentElement || document).appendChild(frame);
                await loaded;
                const controller = frame.contentWindow.navigator.serviceWorker.controller;
                const channel = new MessageChannel();
                const reply = new Promise(resolve => {
                  channel.port1.onmessage = event => resolve(event.data);
                });
                globalThis.__serviceWorkerChildControllerProbe = [
                  "before-post",
                  controller === null,
                  controller instanceof ServiceWorker,
                  controller instanceof frame.contentWindow.ServiceWorker,
                  controller && controller.scriptURL
                ].join("|");
                controller.postMessage({ port: channel.port2 }, [channel.port2]);
                globalThis.__serviceWorkerChildControllerProbe = [
                  "after-reply",
                  controller === null,
                  controller instanceof ServiceWorker,
                  controller instanceof frame.contentWindow.ServiceWorker,
                  controller && controller.scriptURL,
                  await reply
                ].join("|");
              })().catch(error => {
                globalThis.__serviceWorkerChildControllerProbe =
                  "error:" + String(error && error.name) + ":" + String(error && error.message);
              });
            })()
            "#,
    )
    .expect("service worker child frame controller probe should evaluate");

    let expected_worker_url = format!("{base_url}/app/worker.js");
    let expected_frame_url = format!("{base_url}/app/frame.html");
    let expected = format!(
        "after-reply|false|false|true|{expected_worker_url}|child-controller-reply|ExtendableMessageEvent|true|true|true|[object ExtendableMessageEvent]|{base_url}||1|true|WindowClient|true|true|window|nested|{expected_frame_url}|visible|false"
    );
    drain_service_worker_test_until_eval_equals(
        &mut vm,
        &browser_context_runtime,
        &loader,
        "String(globalThis.__serviceWorkerChildControllerProbe)",
        &expected,
    )
    .await;

    server
        .await
        .expect("service worker child controller server should finish");
}

#[tokio::test]
async fn navigator_service_worker_respond_with_wait_until_lifetime_browser_matrix() {
    let (base_url, server) = spawn_service_worker_response_server(vec![(
        "/app/worker.js",
        "text/javascript; charset=utf-8",
        r#"
            self.addEventListener("install", event => {
              event.waitUntil(Promise.resolve());
            });
            self.addEventListener("activate", event => {
              event.waitUntil(clients.claim());
            });

            function waitUntilResult(event) {
              try {
                event.waitUntil(Promise.resolve());
                return "OK";
              } catch (error) {
                return (error && error.name) + ":" + (error instanceof DOMException);
              }
            }

            function report(clientId, message) {
              clients.get(clientId).then(client => {
                if (client) client.postMessage(message);
              });
            }

            function newTaskResponse(body) {
              return new Promise(resolve => {
                setTimeout(() => resolve(new Response(body)), 0);
              });
            }

            self.addEventListener("fetch", event => {
              const step = new URL(event.request.url).search.slice(1);
              if (step === "pending") {
                let resolveResponse;
                const response = new Promise(resolve => {
                  resolveResponse = resolve;
                });
                event.respondWith(response);
                setTimeout(() => {
                  report(event.clientId, step + ":" + waitUntilResult(event));
                  resolveResponse(new Response(step, {status: 218}));
                }, 0);
                return;
              }
              if (step === "same-turn") {
                const response = newTaskResponse(step);
                event.respondWith(response);
                response.then(() => {
                  report(event.clientId, step + ":" + waitUntilResult(event));
                });
                return;
              }
              if (step === "extra-microtask") {
                const response = newTaskResponse(step);
                event.respondWith(response);
                response.then(() => Promise.resolve().then(() => {
                  report(event.clientId, step + ":" + waitUntilResult(event));
                }));
              }
            });
            "#,
    )])
    .await;
    let loader = ResourceRequestClient::new(&moli_fetch::FetchConfig::default()).expect("loader");
    let (mut vm, browser_context_runtime) =
        new_service_worker_page_test_vm_with_loader_and_browser_context_runtime(
            &format!("{base_url}/app/page.html"),
            &loader,
        );

    vm.eval(
        r#"
            (() => {
              globalThis.__serviceWorkerRespondWithWaitUntilProbe = "pending";
              (async () => {
                await navigator.serviceWorker.register("worker.js", { scope: "./" });
                await navigator.serviceWorker.ready;
                const queuedMessages = [];
                const messageResolvers = [];
                navigator.serviceWorker.onmessage = event => {
                  if (messageResolvers.length > 0) {
                    messageResolvers.shift()(event.data);
                  } else {
                    queuedMessages.push(event.data);
                  }
                };
                const nextMessage = () => {
                  if (queuedMessages.length > 0) {
                    return Promise.resolve(queuedMessages.shift());
                  }
                  return new Promise(resolve => messageResolvers.push(resolve));
                };
                const run = async step => {
                  const responsePromise = fetch("api/waituntil?" + step);
                  const message = await nextMessage();
                  const response = await responsePromise;
                  return [response.status, await response.text(), message].join(":");
                };
                globalThis.__serviceWorkerRespondWithWaitUntilProbe = [
                  await run("pending"),
                  await run("same-turn"),
                  await run("extra-microtask")
                ].join("|");
              })().catch(error => {
                globalThis.__serviceWorkerRespondWithWaitUntilProbe =
                  "error:" + String(error && error.name) + ":" + String(error && error.message);
              });
            })()
            "#,
    )
    .expect("service worker respondWith waitUntil probe should evaluate");

    drain_service_worker_test_until_eval_equals(
        &mut vm,
        &browser_context_runtime,
        &loader,
        "String(globalThis.__serviceWorkerRespondWithWaitUntilProbe)",
        "218:pending:pending:OK|200:same-turn:same-turn:OK|200:extra-microtask:extra-microtask:InvalidStateError:true",
    )
    .await;

    server
        .await
        .expect("service worker respondWith waitUntil server should finish");
}

#[tokio::test]
async fn navigator_service_worker_responds_with_body_accessed_default_and_basic_responses() {
    let (base_url, server) = spawn_service_worker_response_server(vec![
        (
            "/app/worker.js",
            "text/javascript; charset=utf-8",
            r#"
            self.addEventListener("install", event => {
              event.waitUntil(Promise.resolve());
            });
            self.addEventListener("activate", event => {
              event.waitUntil(clients.claim());
            });

            function maybeClone(response, cloneMode) {
              if (cloneMode === "clone-response") {
                return response.clone();
              }
              if (cloneMode === "clone-unused") {
                response.clone();
              }
              return response;
            }

            function assertUsableBody(response, label) {
              const body = response.body;
              if (!body || response.bodyUsed || body.locked) {
                throw new Error(label + ":" + [
                  Boolean(body),
                  response.bodyUsed,
                  body && body.locked
                ].join("/"));
              }
            }

            async function passThroughCacheIfNeeded(event, response, cacheMode) {
              if (cacheMode !== "cache") {
                return response;
              }
              const cacheName = event.request.url;
              await self.caches.delete(cacheName);
              const cache = await self.caches.open(cacheName);
              await cache.put(event.request, response);
              const matched = await cache.match(event.request.url);
              matched.body;
              await self.caches.delete(cacheName);
              return matched;
            }

            self.addEventListener("fetch", event => {
              const url = new URL(event.request.url);
              if (!url.pathname.endsWith("/TestRequest")) {
                return;
              }
              const responsePromise = url.searchParams.get("type") === "basic"
                ? fetch("respond-with-body-accessed-response.jsonp")
                : Promise.resolve(new Response("callback('OK');", {
                    status: 213,
                    headers: {"content-type": "application/javascript"}
                  }));
              event.respondWith(responsePromise.then(async response => {
                assertUsableBody(response, "original");
                const selected = maybeClone(response, url.searchParams.get("clone"));
                assertUsableBody(selected, "selected");
                const finalResponse = await passThroughCacheIfNeeded(
                  event,
                  selected,
                  url.searchParams.get("passThroughCache")
                );
                assertUsableBody(finalResponse, "final");
                return finalResponse;
              }));
            });
            "#,
        ),
        (
            "/app/respond-with-body-accessed-response.jsonp",
            "application/javascript",
            "callback('OK');",
        ),
        (
            "/app/respond-with-body-accessed-response.jsonp",
            "application/javascript",
            "callback('OK');",
        ),
        (
            "/app/respond-with-body-accessed-response.jsonp",
            "application/javascript",
            "callback('OK');",
        ),
        (
            "/app/respond-with-body-accessed-response.jsonp",
            "application/javascript",
            "callback('OK');",
        ),
        (
            "/app/respond-with-body-accessed-response.jsonp",
            "application/javascript",
            "callback('OK');",
        ),
        (
            "/app/respond-with-body-accessed-response.jsonp",
            "application/javascript",
            "callback('OK');",
        ),
    ])
    .await;
    let loader = ResourceRequestClient::new(&moli_fetch::FetchConfig::default()).expect("loader");
    let (mut vm, browser_context_runtime) =
        new_service_worker_page_test_vm_with_loader_and_browser_context_runtime(
            &format!("{base_url}/app/page.html"),
            &loader,
        );

    vm.eval(
        r#"
            (() => {
              globalThis.__serviceWorkerBodyAccessedResponseProbe = "pending";
              (async () => {
                await navigator.serviceWorker.register("worker.js", { scope: "./" });
                await navigator.serviceWorker.ready;
                const run = async (type, clone, cacheMode) => {
                  delete globalThis.__serviceWorkerBodyAccessedCallback;
                  const response = await fetch(
                    "TestRequest?type=" + type +
                    "&clone=" + clone +
                    "&passThroughCache=" + cacheMode
                  );
                  const scriptText = await response.text();
                  Function("callback", scriptText)(value => {
                    globalThis.__serviceWorkerBodyAccessedCallback = value;
                  });
                  return [
                    type,
                    clone,
                    cacheMode,
                    response.status,
                    response.headers.get("content-type"),
                    globalThis.__serviceWorkerBodyAccessedCallback
                  ].join(":");
                };
                const runType = async (type, cacheMode) => [
                  await run(type, "none", cacheMode),
                  await run(type, "clone-response", cacheMode),
                  await run(type, "clone-unused", cacheMode)
                ].join(",");
                globalThis.__serviceWorkerBodyAccessedResponseProbe = [
                  await runType("default", "direct"),
                  await runType("default", "cache"),
                  await runType("basic", "direct"),
                  await runType("basic", "cache")
                ].join("|");
              })().catch((error) => {
                globalThis.__serviceWorkerBodyAccessedResponseProbe =
                  "error:" + String(error && error.name) + ":" + String(error && error.message);
              });
            })()
            "#,
    )
    .expect("service worker body-accessed response probe should evaluate");

    drain_service_worker_test_until_eval_equals(
        &mut vm,
        &browser_context_runtime,
        &loader,
        "String(globalThis.__serviceWorkerBodyAccessedResponseProbe)",
        concat!(
            "default:none:direct:213:application/javascript:OK,",
            "default:clone-response:direct:213:application/javascript:OK,",
            "default:clone-unused:direct:213:application/javascript:OK|",
            "default:none:cache:213:application/javascript:OK,",
            "default:clone-response:cache:213:application/javascript:OK,",
            "default:clone-unused:cache:213:application/javascript:OK|",
            "basic:none:direct:200:application/javascript:OK,",
            "basic:clone-response:direct:200:application/javascript:OK,",
            "basic:clone-unused:direct:200:application/javascript:OK|",
            "basic:none:cache:200:application/javascript:OK,",
            "basic:clone-response:cache:200:application/javascript:OK,",
            "basic:clone-unused:cache:200:application/javascript:OK"
        ),
    )
    .await;

    server
        .await
        .expect("service worker body-accessed response server should finish");
}

