async fn spawn_lightweight_popup_response_csp_redirect_external_script_servers() -> (
    String,
    String,
    std::thread::JoinHandle<()>,
    std::thread::JoinHandle<()>,
) {
    let target_listener =
        std::net::TcpListener::bind("127.0.0.1:0").expect("bind popup redirect CSP target server");
    let target_addr = target_listener
        .local_addr()
        .expect("popup redirect CSP target addr");
    let final_script_url = format!("http://{target_addr}/final.js");
    let final_script_url_for_source = final_script_url.clone();
    let target_server = std::thread::spawn(move || {
        use std::io::{Read, Write};

        let mut stream = accept_popup_redirect_test_connection(&target_listener)
            .expect("accept popup redirect CSP final script request");
        let mut buffer = [0; 1024];
        let _ = stream
            .read(&mut buffer)
            .expect("read popup redirect CSP final script request");
        let body = r#"opener.__popupRedirectCspEvents.push("script");"#;
        let response = format!(
            "HTTP/1.1 200 OK\r\nAccess-Control-Allow-Origin: *\r\nContent-Type: application/javascript\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            body.len(),
            body
        );
        stream
            .write_all(response.as_bytes())
            .expect("write popup redirect CSP final script response");
    });

    let source_listener =
        std::net::TcpListener::bind("127.0.0.1:0").expect("bind popup redirect CSP source server");
    let source_addr = source_listener
        .local_addr()
        .expect("popup redirect CSP source addr");
    let source_server = std::thread::spawn(move || {
        use std::io::{Read, Write};

        let mut stream = accept_popup_redirect_test_connection(&source_listener)
            .expect("accept popup redirect CSP document request");
        let mut buffer = [0; 1024];
        let _ = stream
            .read(&mut buffer)
            .expect("read popup redirect CSP document request");
        let body = r#"<!doctype html><script src="/redirect.js"></script>"#;
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Security-Policy: script-src 'self'\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            body.len(),
            body
        );
        stream
            .write_all(response.as_bytes())
            .expect("write popup redirect CSP document response");

        let mut stream = accept_popup_redirect_test_connection(&source_listener)
            .expect("accept popup redirect CSP script request");
        let _ = stream
            .read(&mut buffer)
            .expect("read popup redirect CSP script request");
        let response = format!(
            "HTTP/1.1 302 Found\r\nLocation: {final_script_url_for_source}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
        );
        stream
            .write_all(response.as_bytes())
            .expect("write popup redirect CSP redirect response");
    });
    (
        format!("http://{source_addr}/popup.html"),
        final_script_url,
        source_server,
        target_server,
    )
}

fn accept_popup_redirect_test_connection(
    listener: &std::net::TcpListener,
) -> std::io::Result<std::net::TcpStream> {
    listener.set_nonblocking(true)?;
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        match listener.accept() {
            Ok((stream, _)) => {
                // Accepted sockets can inherit O_NONBLOCK from the listener on
                // some platforms. The request bytes are allowed to arrive
                // after accept, so restore blocking I/O with a bounded timeout
                // before the fixture reads the request head.
                stream.set_nonblocking(false)?;
                stream.set_read_timeout(Some(std::time::Duration::from_secs(5)))?;
                stream.set_write_timeout(Some(std::time::Duration::from_secs(5)))?;
                return Ok(stream);
            }
            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                if std::time::Instant::now() >= deadline {
                    return Err(std::io::Error::new(
                        std::io::ErrorKind::TimedOut,
                        "timed out waiting for popup redirect test connection",
                    ));
                }
                std::thread::sleep(std::time::Duration::from_millis(5));
            }
            Err(error) => return Err(error),
        }
    }
}
#[test]
fn details_dialog_string_boundaries_use_webidl_conversion() {
    let mut vm = new_storage_test_vm("https://example.com/");

    let result = vm
        .eval(
            r#"
            (() => {
              const probe = callback => {
                try {
                  callback();
                  return "ok";
                } catch (error) {
                  return error && error.name;
                }
              };

              const details = document.createElement("details");
              details.name = null;
              const detailsNull = details.name;
              details.name = undefined;
              const detailsUndefined = details.name;
              details.name = { toString() { return "group"; } };
              const detailsObject = details.name;
              const detailsSymbol = probe(() => { details.name = Symbol("name"); });
              const detailsAfterSymbol = details.name;
              const detailsThrow = probe(() => {
                details.name = { toString() { throw new RangeError("name"); } };
              });
              const detailsAfterThrow = details.name;

              const dialog = document.createElement("dialog");
              dialog.returnValue = null;
              const returnNull = dialog.returnValue;
              dialog.returnValue = undefined;
              const returnUndefined = dialog.returnValue;
              dialog.returnValue = { toString() { return "return object"; } };
              const returnObject = dialog.returnValue;
              const returnSymbol = probe(() => { dialog.returnValue = Symbol("return"); });
              const returnAfterSymbol = dialog.returnValue;

              dialog.returnValue = "seed";
              dialog.open = true;
              dialog.close();
              const closeNoArg = `${dialog.returnValue}:${dialog.open}`;
              dialog.open = true;
              dialog.close(undefined);
              const closeUndefined = `${dialog.returnValue}:${dialog.open}`;
              dialog.open = true;
              dialog.close({ toString() { return "closed object"; } });
              const closeObject = `${dialog.returnValue}:${dialog.open}`;
              dialog.open = true;
              const closeSymbol = probe(() => dialog.close(Symbol("close")));
              const closeAfterSymbol = `${dialog.returnValue}:${dialog.open}`;
              const closeThrow = probe(() => {
                dialog.close({ toString() { throw new RangeError("close"); } });
              });
              const closeAfterThrow = `${dialog.returnValue}:${dialog.open}`;

              return JSON.stringify({
                detailsNull,
                detailsUndefined,
                detailsObject,
                detailsSymbol,
                detailsAfterSymbol,
                detailsThrow,
                detailsAfterThrow,
                returnNull,
                returnUndefined,
                returnObject,
                returnSymbol,
                returnAfterSymbol,
                closeNoArg,
                closeUndefined,
                closeObject,
                closeSymbol,
                closeAfterSymbol,
                closeThrow,
                closeAfterThrow
              });
            })()
            "#,
        )
        .expect("details/dialog string boundary probe should evaluate");

    assert_eq!(
        result,
        r#"{"detailsNull":"null","detailsUndefined":"undefined","detailsObject":"group","detailsSymbol":"TypeError","detailsAfterSymbol":"group","detailsThrow":"RangeError","detailsAfterThrow":"group","returnNull":"null","returnUndefined":"undefined","returnObject":"return object","returnSymbol":"TypeError","returnAfterSymbol":"return object","closeNoArg":"seed:false","closeUndefined":"seed:false","closeObject":"closed object:false","closeSymbol":"TypeError","closeAfterSymbol":"closed object:true","closeThrow":"RangeError","closeAfterThrow":"closed object:true"}"#
    );
}
#[test]
fn history_state_rejects_webassembly_module_for_storage() {
    let mut vm = new_storage_test_vm("https://example.com/wasm-history");

    let result = vm
        .eval(
            r#"
            (() => {
              const createModule = () => new WebAssembly.Module(
                new Uint8Array([0, 97, 115, 109, 1, 0, 0, 0])
              );
              const probe = (method, value) => {
                try {
                  history[method](value, "");
                  return "ok";
                } catch (error) {
                  return error && error.name;
                }
              };

              let before = false;
              let after = false;
              const interleaved = probe("pushState", [
                { get x() { before = true; return 1; } },
                createModule(),
                { get x() { after = true; return 2; } }
              ]);

              return [
                probe("pushState", createModule()),
                probe("replaceState", createModule()),
                interleaved,
                before,
                after
              ].join("|");
            })()
            "#,
        )
        .expect("history WebAssembly.Module storage rejection should evaluate");

    assert_eq!(
        result,
        "DataCloneError|DataCloneError|DataCloneError|true|false"
    );
}
#[test]
fn notification_data_rejects_webassembly_module_for_storage() {
    let mut vm = new_storage_test_vm("https://example.com/wasm-notification");

    let result = vm
        .eval(
            r#"
            (() => {
              const createModule = () => new WebAssembly.Module(
                new Uint8Array([0, 97, 115, 109, 1, 0, 0, 0])
              );
              const probe = (value) => {
                try {
                  new Notification("title", { data: value });
                  return "ok";
                } catch (error) {
                  return error && error.name;
                }
              };

              let before = false;
              let after = false;
              const interleaved = probe([
                { get x() { before = true; return 1; } },
                createModule(),
                { get x() { after = true; return 2; } }
              ]);
              const plain = new Notification("plain", { data: { answer: 42 } });
              const missing = new Notification("missing");
              const explicitUndefined = new Notification(
                "explicit",
                { data: undefined }
              );
              const constructorActions = (() => {
                try {
                  new Notification("actions", {
                    actions: [{ action: "reply", title: "Reply" }]
                  });
                  return "ok";
                } catch (error) {
                  return error && error.name;
                }
              })();

              return [
                typeof Notification,
                Notification.permission,
                Notification.maxActions,
                typeof Notification.requestPermission,
                plain.title,
                plain.actions.length,
                plain.data.answer,
                missing.data === null,
                explicitUndefined.data === null,
                constructorActions,
                probe(createModule()),
                interleaved,
                before,
                after
              ].join("|");
            })()
            "#,
        )
        .expect("Notification WebAssembly.Module storage rejection should evaluate");

    assert_eq!(
        result,
        "function|default|2|function|plain|0|42|true|true|TypeError|DataCloneError|DataCloneError|true|false"
    );
}

#[test]
fn notification_options_project_metadata_fields() {
    let mut vm = new_storage_test_vm("https://example.com/notification-metadata");

    let result = vm
        .eval(
            r#"
            (() => {
              const notification = new Notification("rich", {
                body: "Body",
                icon: "/icon.png",
                image: "/image.png",
                badge: "/badge.png",
                dir: "rtl",
                lang: "fr",
                vibrate: [1, 2],
                timestamp: 1234,
                renotify: true,
                silent: false,
                requireInteraction: true,
                data: { answer: 42 }
              });
              const single = new Notification("single", { vibrate: 9 });
              const defaults = new Notification("defaults");
              const descriptorShape = name => {
                const descriptor = Object.getOwnPropertyDescriptor(
                  Notification.prototype,
                  name
                );
                return [
                  name,
                  typeof descriptor?.get,
                  descriptor?.get?.name,
                  descriptor?.get?.length,
                  typeof descriptor?.set,
                  descriptor?.enumerable,
                  descriptor?.configurable
                ].join(":");
              };

              return JSON.stringify({
                rich: [
                  notification.body,
                  notification.icon,
                  notification.image,
                  notification.badge,
                  notification.dir,
                  notification.lang,
                  Array.from(notification.vibrate).join("/"),
                  notification.timestamp,
                  notification.renotify,
                  notification.silent,
                  notification.requireInteraction,
                  notification.data.answer
                ].join("|"),
                singleVibrate: Array.from(single.vibrate).join("/"),
                defaults: [
                  defaults.body,
                  defaults.icon,
                  defaults.image,
                  defaults.badge,
                  defaults.dir,
                  defaults.lang,
                  defaults.vibrate.length,
                  defaults.timestamp,
                  defaults.renotify,
                  defaults.silent === null,
                  defaults.requireInteraction
                ].join("|"),
                descriptors: [
                  "body",
                  "icon",
                  "image",
                  "badge",
                  "dir",
                  "lang",
                  "vibrate",
                  "timestamp",
                  "renotify",
                  "silent",
                  "requireInteraction"
                ].map(descriptorShape).join(",")
              });
            })()
            "#,
        )
        .expect("Notification metadata projection should evaluate");

    assert_eq!(
        result,
        r#"{"rich":"Body|/icon.png|/image.png|/badge.png|rtl|fr|1/2|1234|true|false|true|42","singleVibrate":"9","defaults":"||||auto||0|0|false|true|false","descriptors":"body:function:get body:0:undefined:true:true,icon:function:get icon:0:undefined:true:true,image:function:get image:0:undefined:true:true,badge:function:get badge:0:undefined:true:true,dir:function:get dir:0:undefined:true:true,lang:function:get lang:0:undefined:true:true,vibrate:function:get vibrate:0:undefined:true:true,timestamp:function:get timestamp:0:undefined:true:true,renotify:function:get renotify:0:undefined:true:true,silent:function:get silent:0:undefined:true:true,requireInteraction:function:get requireInteraction:0:undefined:true:true"}"#
    );
}

#[test]
fn notification_permission_tracks_permission_overrides_and_request_permission() {
    fn notifications_override(
        setting: &str,
    ) -> crate::protocol_types::PermissionOverrideRegistration {
        crate::protocol_types::PermissionOverrideRegistration {
            permission: serde_json::Value::String("notifications".to_owned()),
            setting: setting.to_owned(),
            origin: None,
            embedded_origin: None,
        }
    }

    fn request_permission_result(vm: &mut ScriptVm) -> String {
        vm.eval(
            r#"
            (() => {
              globalThis.__notificationPermissionRequest = "pending";
              Notification.requestPermission().then(
                value => { globalThis.__notificationPermissionRequest = value; },
                error => {
                  globalThis.__notificationPermissionRequest = "error:" + error.name;
                }
              );
            })()
            "#,
        )
        .expect("Notification.requestPermission probe should evaluate");
        vm.eval("String(globalThis.__notificationPermissionRequest)")
            .expect("Notification.requestPermission result should evaluate")
    }

    let mut vm = new_storage_test_vm("https://example.com/notification-permission");
    assert_eq!(
        vm.eval("Notification.permission")
            .expect("Notification.permission should evaluate"),
        "default"
    );
    assert_eq!(request_permission_result(&mut vm), "default");

    vm.set_permission_overrides(&[notifications_override("granted")]);
    assert_eq!(
        vm.eval("Notification.permission")
            .expect("Notification.permission override should evaluate"),
        "granted"
    );
    assert_eq!(request_permission_result(&mut vm), "granted");

    vm.set_permission_overrides(&[notifications_override("denied")]);
    assert_eq!(
        vm.eval("Notification.permission")
            .expect("Notification.permission denied override should evaluate"),
        "denied"
    );
    assert_eq!(request_permission_result(&mut vm), "denied");

    let mut insecure_vm = new_storage_test_vm("http://insecure-notification.test/");
    insecure_vm.set_permission_overrides(&[notifications_override("granted")]);
    assert_eq!(
        insecure_vm
            .eval("Notification.permission")
            .expect("insecure Notification.permission should evaluate"),
        "denied"
    );
    assert_eq!(request_permission_result(&mut insecure_vm), "denied");
}

#[test]
fn notification_declared_surface_uses_private_slots_and_methods() {
    let mut vm = new_storage_test_vm("https://example.com/notification-declared");

    let result = vm
        .eval(
            r#"
            (() => {
              const notification = new Notification("real", {
                data: { answer: 42 }
              });
              const internalOwn = Object.getOwnPropertyNames(notification)
                .filter(name =>
                  name.startsWith("__lmNotification") ||
                  name === "__moliEventTargetSlot" ||
                  name === "__moliSimpleEventTargetOrderedHandlers"
                )
                .join(",");

              Object.assign(Notification.prototype, {
                __lmNotificationTitle: "prototype-poison",
                __lmNotificationData: { answer: 0 },
                __moliEventTargetSlot: "prototypeListeners",
                __moliSimpleEventTargetOrderedHandlers: false
              });
              Object.assign(notification, {
                __lmNotificationTitle: "own-poison",
                __lmNotificationData: { answer: 1 },
                __moliEventTargetSlot: "ownListeners",
                __moliSimpleEventTargetOrderedHandlers: false
              });

              const summarize = (target, name) => {
                const descriptor = Object.getOwnPropertyDescriptor(target, name);
                return [
                  !!descriptor,
                  descriptor && descriptor.enumerable,
                  descriptor && descriptor.configurable,
                  descriptor && descriptor.writable,
                  descriptor && typeof descriptor.value,
                  descriptor && descriptor.value.length,
                  descriptor && descriptor.value.name
                ].join(":");
              };
              const accessorDescriptor = name => {
                const descriptor = Object.getOwnPropertyDescriptor(Notification.prototype, name);
                return [
                  name,
                  typeof descriptor?.get,
                  descriptor?.get?.name,
                  descriptor?.get?.length,
                  typeof descriptor?.set,
                  descriptor?.enumerable,
                  descriptor?.configurable
                ].join(":");
              };

              const titleGetter =
                Object.getOwnPropertyDescriptor(Notification.prototype, "title").get;
              const dataGetter =
                Object.getOwnPropertyDescriptor(Notification.prototype, "data").get;
              const getter = name =>
                Object.getOwnPropertyDescriptor(Notification.prototype, name).get;
              const outcome = callback => {
                try {
                  const value = callback();
                  return value === undefined ? "undefined" : String(value);
                } catch (error) {
                  return `throw:${error && error.name}`;
                }
              };
              const fake = {
                __lmNotificationBrand: true,
                __lmNotificationTitle: "fake-title",
                __lmNotificationData: { answer: 99 },
                __lmNotificationBody: "fake-body",
                __lmNotificationVibrate: [3, 4],
                __lmNotificationTimestamp: 99,
                __lmNotificationRenotify: true,
                __lmNotificationSilent: false,
                __lmNotificationRequireInteraction: true,
                __lmNotificationActions: [{ action: "fake", title: "Fake" }],
                __lmNotificationRecordId: 1n,
                __lmNotificationRecordRegistrationId: 1n
              };
              const events = [];
              notification.addEventListener("show", () => events.push("listener"));
              const allowed = notification.dispatchEvent(new Event("show"));

              return [
                internalOwn || "none",
                [accessorDescriptor("title"), accessorDescriptor("data"), accessorDescriptor("actions")].join(","),
                notification.title,
                notification.data.answer,
                notification.actions.length,
                [
                  outcome(() => titleGetter.call(fake)),
                  outcome(() => dataGetter.call(fake)),
                  outcome(() => getter("body").call(fake)),
                  outcome(() => getter("vibrate").call(fake)),
                  outcome(() => getter("timestamp").call(fake)),
                  outcome(() => getter("renotify").call(fake)),
                  outcome(() => getter("silent").call(fake)),
                  outcome(() => getter("requireInteraction").call(fake)),
                  outcome(() => getter("actions").call(fake)),
                  outcome(() => notification.close.call(fake))
                ].join(","),
                [
                  outcome(() => notification.addEventListener.call(fake, "show", () => {})),
                  outcome(() => notification.removeEventListener.call(fake, "show", () => {})),
                  outcome(() => notification.dispatchEvent.call(fake, new Event("show")))
                ].join(","),
                Object.keys(Notification).includes("requestPermission"),
                summarize(Notification, "requestPermission"),
                Object.keys(notification).includes("addEventListener"),
                summarize(notification, "addEventListener"),
                summarize(notification, "removeEventListener"),
                summarize(notification, "dispatchEvent"),
                allowed,
                events.join(",")
              ].join("|");
            })()
            "#,
        )
        .expect("Notification declared surface probe should evaluate");

    assert_eq!(
        result,
        "none|title:function:get title:0:undefined:true:true,data:function:get data:0:undefined:true:true,actions:function:get actions:0:undefined:true:true|real|42|0|throw:TypeError,throw:TypeError,throw:TypeError,throw:TypeError,throw:TypeError,throw:TypeError,throw:TypeError,throw:TypeError,throw:TypeError,throw:TypeError|throw:TypeError,throw:TypeError,throw:TypeError|true|true:true:true:true:function:0:requestPermission|true|true:true:true:true:function:0:addEventListener|true:true:true:true:function:0:removeEventListener|true:true:true:true:function:0:dispatchEvent|true|listener"
    );
}

#[test]
fn zhihu_probe_native_names_match_chromium_shape() {
    let mut vm = new_storage_test_vm("https://example.com/");

    let result = vm
        .eval(
            r#"
            (() => {
              const nativeNamed = (value, name) =>
                typeof value === "function" &&
                value.name === name &&
                new RegExp(`^function ${name}\\(`).test(String(value)) &&
                /\[native code\]/.test(String(value));
              const namedGetter = (owner, key, name) => {
                const getter = Object.getOwnPropertyDescriptor(owner, key)?.get;
                return typeof getter === "function" &&
                  getter.name === `get ${name}` &&
                  new RegExp(`^function get ${name}\\(`).test(String(getter)) &&
                  /\[native code\]/.test(String(getter));
              };
              return JSON.stringify({
                open: nativeNamed(window.open, "open"),
                print: nativeNamed(window.print, "print"),
                stop: nativeNamed(window.stop, "stop"),
                blur: nativeNamed(window.blur, "blur"),
                find: nativeNamed(window.find, "find"),
                getRandomValues: nativeNamed(crypto.getRandomValues, "getRandomValues"),
                isTypeSupported: nativeNamed(MediaSource.isTypeSupported, "isTypeSupported"),
                documentAllGetter: namedGetter(Document.prototype, "all", "all"),
                webdriverGetter: namedGetter(Navigator.prototype, "webdriver", "webdriver"),
                screenAvailWidthGetter: namedGetter(Screen.prototype, "availWidth", "availWidth")
              });
            })()
            "#,
        )
        .expect("native function naming probe should evaluate");

    assert_eq!(
        result,
        r#"{"open":true,"print":true,"stop":true,"blur":true,"find":true,"getRandomValues":true,"isTypeSupported":true,"documentAllGetter":true,"webdriverGetter":true,"screenAvailWidthGetter":true}"#
    );
}
#[test]
fn quota_exceeded_error_is_dom_exception_subclass_with_readonly_slots() {
    let mut vm = new_storage_test_vm("https://quota-exceeded.test/");

    let result = vm
        .eval(
            r#"
            (() => {
              const explicit = new QuotaExceededError("full", { requested: 7, quota: 11 });
              const empty = new QuotaExceededError();
              let thrown;
              try {
                crypto.getRandomValues(new Uint8Array(65537));
              } catch (error) {
                thrown = error;
              }

              const requestedDescriptor =
                Object.getOwnPropertyDescriptor(QuotaExceededError.prototype, "requested");
              const quotaDescriptor =
                Object.getOwnPropertyDescriptor(QuotaExceededError.prototype, "quota");
              const domNamed = new DOMException("named", "QuotaExceededError");

              return [
                explicit.name,
                explicit.message,
                explicit.code,
                explicit.requested,
                explicit.quota,
                explicit instanceof QuotaExceededError,
                explicit instanceof DOMException,
                Object.getPrototypeOf(explicit) === QuotaExceededError.prototype,
                Object.getPrototypeOf(QuotaExceededError.prototype) === DOMException.prototype,
                Object.prototype.hasOwnProperty.call(explicit, "requested"),
                typeof requestedDescriptor.get,
                requestedDescriptor.get.name,
                requestedDescriptor.get.length,
                requestedDescriptor.set === undefined,
                requestedDescriptor.enumerable,
                requestedDescriptor.configurable,
                typeof quotaDescriptor.get,
                quotaDescriptor.get.name,
                quotaDescriptor.get.length,
                quotaDescriptor.set === undefined,
                quotaDescriptor.enumerable,
                quotaDescriptor.configurable,
                empty.requested === null,
                empty.quota === null,
                thrown instanceof QuotaExceededError,
                thrown.requested === null,
                thrown.quota === null,
                domNamed instanceof QuotaExceededError,
                domNamed.name,
                domNamed.code
              ].join("|");
            })()
            "#,
        )
        .expect("QuotaExceededError shape probe should evaluate");

    assert_eq!(
        result,
        "QuotaExceededError|full|22|7|11|true|true|true|true|false|function|get requested|0|true|true|true|function|get quota|0|true|true|true|true|true|true|true|true|false|QuotaExceededError|22"
    );
}
